export function validSavedDiagnosticTurn(value:unknown,conversationId:string):value is Conversation['turns'][number]{try{const t=value as Conversation['turns'][number];return !!t&&typeof t.id==='string'&&t.captureId===conversationId+'/'+t.id&&t.diagnosticPolicyVersion===1&&!!t.diagnosticCapture&&typeof t.question==='string'&&typeof t.routingQuestion==='string'&&!!t.requestContext&&!!t.context&&['manager','supervisor','maintenance','safety','viewer'].includes(t.actor)&&Array.isArray(t.commands)&&t.commands.length===0&&!!t.workflowSnapshot&&!!t.view&&validateWorkflow(t.workflowSnapshot)&&validCapturedView(t.workflowSnapshot,t.view,t.asOf,true)&&validCapturedAnswer(t)&&validCapturedSemantics(t);}catch{return false}}
